<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Add / Update Exam Marks</h1><p>Select a configured exam subject and save all student marks transactionally.</p></div></header><form class="filter-bar filter-bar--compact"><div class="module-field"><label>Exam / Class / Subject</label><select class="module-select" name="setup" required><option value="">Select setup</option><?php foreach($setups as$s):?><option value="<?= $s['id'] ?>" <?= $selectedSetup==$s['id']?'selected':'' ?>><?= e($s['exam_name'].' — '.$s['class_name'].' — '.$s['subject_name']) ?></option><?php endforeach ?></select></div><button class="btn btn--secondary">Load Students</button></form><?php if($selectedSetup):?><form method="post" action="<?= url('/admin/exams/marks') ?>"><?= csrf_field() ?><input type="hidden" name="exam_subject_id" value="<?= $selectedSetup ?>"><section class="module-card"><div class="module-card__body"><table class="data-table"><thead><tr><th>Registration</th><th>Student</th><th>Marks</th><th>Maximum</th></tr></thead><tbody><?php foreach($students as$s):?><tr><td><?= e($s['registration_no']) ?></td><td><?= e($s['student_name']) ?></td><td><input class="module-input" type="number" min="0" max="<?= e($s['total_marks']) ?>" step="0.01" name="marks[<?= $s['id'] ?>]" value="<?= e($s['obtained_marks']??'') ?>" required></td><td><?= e($s['total_marks']) ?></td></tr><?php endforeach ?></tbody></table><button class="btn btn--primary">Save Marks</button></div></section></form><?php endif ?></div></div></main>
